import{z as n,x as d,o as e,c as B,q as A,j as o,D as E,d as l,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"模型卡与报告","description":"","frontmatter":{"title":"模型卡与报告","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-cards.md","filePath":"llm/model-cards.md","lastUpdated":1791063341000}'),p={name:"llm/model-cards.md"};function m(D,a,h,c,f,C){const r=d("Mermaid");return e(),B("div",null,[a[2]||(a[2]=A('<h1 id="模型卡与报告" tabindex="-1">模型卡与报告 <a class="header-anchor" href="#模型卡与报告" aria-label="Permalink to &quot;模型卡与报告&quot;">​</a></h1><div class="epigraph"><p>模型卡不是营销页。它记录预期用途、评测条件、失败模式与数据边界，让下一手决定能不能接这个权重。</p><footer>—— Mitchell 等, Model Cards for Model Reporting</footer></div><p><a href="/llm/benchmark-saturation">上一课</a>要求把饱和卷降级。若报告里只留一张高峰表，降级不会发生。本课写模型卡。协议单元在此收束：数字怎么来，要能写进一张可审计的卡。下一单元换裁判——卡上的「更好用」往往来自法官或人，而不是 harness。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mitchell 等人把模型卡写成类似数据表的短文档：谁训练的、训练数据边界、预期用户、量化指标、伦理考量。LLM 时代还要加：聊天模板、上下文长度、工具接口、<a href="/llm/eval-contamination">污染</a>重叠表、评测框架哈希、解码超参。缺任何一项，外部就无法复现你卡上的数字。</p><p><span class="marginnote">「聊天模板」是各家模型自定的对话包装格式——同一句「你好」，有的要包成 <code>&lt;|user|&gt;</code> 风格的标签，有的用别的记号。包装错了，同一个权重能掉十几分。卡上必须写模板，读卡的人才能原样复现。</span></p><p>常见失败：用 Arena 分代理数学能力；用英文榜代理多语言产品；把量化前后的 PPL 当唯一质量声明。本课程前十课拆开的仪器，应在卡上分栏出现，而不是折成一个「综合分」。</p><p><span class="marginnote">开源权重的模型卡还要写清许可证与训练数据是否可审计。只写「混合互联网数据」等于不可审计，与 Dolma 一类公开配方不在同一证据层级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小栏目：用途与非用途；架构与上下文；训练数据与截止日期；评测表（任务、协议、框架版本、是否 CoT / 工具）；已知失败模式；安全与拒答行为的概述（细节走后课危险能力，不在此展开攻击面）；环境与能耗若可测则写。每条分数旁注明仪器，不把 Elo、ECE、pass@1 排进同一列排序。</p><p><span class="marginnote">模型卡类比药品说明书：不只写「疗效如何」（高峰分），还要写适应症（预期用途）、禁忌（非用途）、副作用（失败模式）、批号与有效期（数据截止、框架版本）。没有说明书的药不敢吃，没有卡的权重不该直接上线。</span></p><p>更新权重要发新卡或明确 diff，禁止在旧卡上静默改数。</p>',12)),(e(),o(i,null,{default:E(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20INST%5B%22%E4%BB%AA%E5%99%A8%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20INST%20--%3E%20CARD%5B%22%E6%A8%A1%E5%9E%8B%E5%8D%A1%E6%A0%8F%E7%9B%AE%22%5D%0A%20%20CARD%20--%3E%20USE%5B%22%E7%94%A8%E9%80%94%20%2F%20%E9%9D%9E%E7%94%A8%E9%80%94%22%5D%0A%20%20CARD%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"卡的读者是部署者，不是排行榜观众。部署者需要的是条件：在什么提示、什么语言、什么工具下，哪些数字成立。把条件写全，分数才会从广告变回测量。省略条件等价于声称无条件成立，这在饱和与格式敏感之后已经不成立。",-1)),(e(),o(i,null,{default:E(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%96%B0%E6%9D%83%E9%87%8D%E5%88%B0%E6%89%8B%22%5D%20--%3E%20R%7B%22%E5%8D%A1%E4%B8%8A%E5%86%99%E5%85%A8%E6%9D%A1%E4%BB%B6%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20R%20--%3E%7C%22%E6%A8%A1%E6%9D%BF%E3%80%81%E4%B8%8A%E4%B8%8B%E6%96%87%E3%80%81%E8%AF%AD%E8%A8%80%E3%80%81%E5%B7%A5%E5%85%B7%22%7C%20Y%5B%22%E6%8C%89%E5%90%8C%E5%8D%8F%E8%AE%AE%E5%A4%8D%E6%B5%8B%E5%85%B3%E9%94%AE%E6%95%B0%E5%AD%97%22%5D%0A%20%20R%20--%3E%7C%22%E5%8F%AA%E6%9C%89%E7%BB%BC%E5%90%88%E5%88%86%22%7C%20N%5B%22%E8%A7%86%E4%B8%BA%E5%B9%BF%E5%91%8A%EF%BC%9A%E9%80%80%E5%9B%9E%E8%A1%A5%E5%8D%A1%E6%88%96%E8%87%AA%E6%B5%8B%22%5D%0A%20%20Y%20--%3E%20OK%5B%22%E5%AF%B9%E7%85%A7%E5%B7%B2%E7%9F%A5%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%E8%AF%84%E4%BC%B0%E9%A3%8E%E9%99%A9%22%5D%0A%20%20OK%20--%3E%20GO%5B%22%E5%86%B3%E5%AE%9A%E6%8E%A5%E5%85%A5%E3%80%81%E9%99%90%E5%9F%9F%E6%88%96%E5%BC%83%E7%94%A8%22%5D%0A%20%20N%20--%3E%20BACK%5B%22%E8%A6%81%E6%B1%82%E6%A8%A1%E5%9E%8B%E6%96%B9%E5%8F%91%E6%96%B0%E5%8D%A1%E6%88%96%20diff%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型卡不替代安全报告或数据卡（Gebru 等 Datasheets）。下一单元从「谁来判开放生成」开始，那些数字更依赖协议，更需要写进卡的脚注。</p><p><span class="marginnote">「静默改数」为什么被禁止？下游按旧卡的数字做了容量与质量决策，权重一换、卡没换，线上表现悄悄偏离假设——出故障时谁也不会想到去对模型卡。卡与权重一起变版本，是让「下一手」敢接的基础。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型卡记录条件与边界，不只记录高峰分。</li><li>不同仪器分栏；饱和卷标明为回归门槛。</li><li>权重更新必须有卡的 diff。</li><li>出处：Mitchell 等 <em>Model Cards for Model Reporting</em>；数据侧对照 Gebru 等 Datasheets。</li></ul>',5))])}const T=n(p,[["render",m]]);export{_ as __pageData,T as default};
